function UICultivateObserveDialog:RefreshSlider(posZ)
    local minZ, maxZ = self.minZ, self.maxZ
    local value = (maxZ - posZ) / (maxZ - minZ)
    self.Slider.value = value

end

function UICultivateObserveDialog:CalcPosZ(curZ, offset)
    local minZ, maxZ = self.minZ, self.maxZ
    local posZ = curZ - offset
    if posZ >= maxZ then
        posZ = maxZ
    elseif posZ <= minZ then
        posZ = minZ
    end
    return posZ
end

function UICultivateObserveDialog:RefreshSliderByOffset(offset)
    local virtualCamera = self.virtualCamera
    local curPosition   = virtualCamera.transform.localPosition
    local posZ          = self:CalcPosZ(curPosition.z, offset)
    local minZ, maxZ    = self.minZ, self.maxZ
    self.posZ = posZ
    self:RefreshSlider(posZ)
end

function UICultivateObserveDialog:RefreshUIShowState(isShow)
    KTool.SetActive(self.Container.gameObject, isShow)
end

